pub(crate) fn overlay<'a>(catalog: &'a crate::app::state::AppsCatalogState, i18n: crate::app::i18n::I18n, theme: &iced::Theme, base: iced::Element<'a, crate::app::Message>) -> iced::Element<'a, crate::app::Message> {
    desktop_settings_apps::system_settings_apps::preferences_view::overlay(&catalog.preferences, &catalog.host, &catalog.rows, base, |title, description, size| { if size == 28 { crate::app::components::system_settings_common::settings_page_heading_with_help(i18n, theme, i18n.__(title), i18n.__(description)) } else { crate::app::components::system_settings_common::settings_group_heading_with_help(i18n, theme, i18n.__(title), i18n.__(description)) } }, super::event)
}
